import json
import re
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation and return a concise text summary
    of decision-relevant features. Must never raise, never return empty.
    """
    try:
        obs = observation_history[-1]

        # Try to extract grid from observation
        grid = None

        # Method 1: ARC integer grid format (look for <grid_k> markers)
        grid_match = re.search(r'<grid_\d+>', obs)
        if grid_match:
            # Find the start of the grid data (after the marker line)
            marker_end = grid_match.end()
            lines_after = obs[marker_end:].strip().split('\n')

            # Parse rows - each row should be like [14, 14, 14, ...]
            rows = []
            for line in lines_after:
                line = line.strip()
                if line.startswith('[') and line.endswith(']'):
                    try:
                        # Parse the list of integers
                        row_str = line[1:-1]  # Remove brackets
                        row = [int(x.strip()) for x in row_str.split(',')]
                        if row:
                            rows.append(row)
                    except (ValueError, IndexError):
                        continue
                elif line == '' or line.startswith('<') or line.startswith('='):
                    # Stop at next marker or end
                    if not rows:
                        continue
                    break

            if rows:
                grid = rows

        # Method 2: JSON 2D array of color names
        if grid is None:
            # Find the outermost [[ ... ]] structure
            start = obs.find('[[')
            end = obs.rfind(']]')
            if start != -1 and end != -1:
                try:
                    grid_json = obs[start:end+2]
                    parsed = json.loads(grid_json)
                    if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                        grid = parsed
                except (json.JSONDecodeError, IndexError):
                    pass

        if grid is None:
            # Fallback: look for any JSON array pattern
            try:
                # Try to find any JSON array in the text
                for pattern in [r'\[\[.*?\]\]', r'\[.*?\]']:
                    match = re.search(pattern, obs, re.DOTALL)
                    if match:
                        candidate = match.group()
                        parsed = json.loads(candidate)
                        if isinstance(parsed, list) and len(parsed) > 0:
                            if isinstance(parsed[0], list):
                                grid = parsed
                                break
            except (json.JSONDecodeError, AttributeError):
                pass

        if grid is None:
            # Last resort: return a minimal non-empty summary
            return "(empty_grid)"

        # Analyze the grid
        rows_count = len(grid)
        cols_count = len(grid[0]) if rows_count > 0 else 0

        # Identify non-background cells
        # Count color frequencies to determine background
        color_counts = {}
        for row in grid:
            for cell in row:
                color_counts[cell] = color_counts.get(cell, 0) + 1

        if not color_counts:
            return "(empty_grid)"

        # Find the most common color (background)
        background = max(color_counts, key=color_counts.get)

        # Collect non-background cells
        non_bg_cells = []
        for r in range(rows_count):
            for c in range(cols_count):
                cell = grid[r][c]
                if cell != background:
                    # Convert to a simple representation
                    if isinstance(cell, int):
                        color_name = _int_to_color_name(cell)
                    else:
                        color_name = str(cell)
                    non_bg_cells.append((r, c, color_name))

        # Build the summary
        summary_parts = []
        summary_parts.append(f"grid={rows_count}x{cols_count}")
        summary_parts.append(f"bg={_color_to_str(background)}")

        if non_bg_cells:
            # Group cells by color for compact representation
            cells_by_color = {}
            for r, c, color in non_bg_cells:
                if color not in cells_by_color:
                    cells_by_color[color] = []
                cells_by_color[color].append((r, c))

            color_parts = []
            for color, positions in sorted(cells_by_color.items()):
                pos_str = ";".join([f"{r},{c}" for r, c in sorted(positions)])
                color_parts.append(f"{color}:{pos_str}")

            summary_parts.append("objs=" + "|".join(color_parts))
        else:
            summary_parts.append("objs=none")

        return " ".join(summary_parts)

    except Exception as e:
        # Never raise, return a safe non-empty string
        return f"(error:{str(e)[:50]})"


def _int_to_color_name(val: int) -> str:
    """Convert integer color code to name string."""
    color_map = {
        0: "blk",    # black
        1: "blu",    # blue
        2: "red",    # red
        3: "grn",    # green
        4: "ylw",    # yellow
        5: "lgry",   # light-gray
        6: "mag",    # magenta
        7: "orn",    # orange
        8: "lblu",   # light-blue
        9: "mrn",    # maroon
        10: "wht",   # white
        11: "dgry",  # dark-gray
    }
    return color_map.get(val, f"c{val}")


def _color_to_str(color) -> str:
    """Convert a color value to a short string."""
    if isinstance(color, int):
        return _int_to_color_name(color)
    elif isinstance(color, str):
        # Shorten common color names
        short = {
            "black": "blk", "blue": "blu", "red": "red", "green": "grn",
            "yellow": "ylw", "gray": "gry", "lightgray": "lgry",
            "light-gray": "lgry", "magenta": "mag", "orange": "orn",
            "lightblue": "lblu", "light-blue": "lblu", "darkgreen": "dgrn",
            "dark-red": "mrn", "maroon": "mrn", "white": "wht",
            "darkgray": "dgry", "dark-gray": "dgry", "gold": "gld"
        }
        return short.get(color.lower(), color[:4])
    return str(color)

import json
import re
from typing import List, Tuple, Optional, Any

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation and return a concise text summary
    of decision-relevant features. Must never raise, never return empty.
    """
    try:
        obs = observation_history[-1]
        # Default values if parsing fails
        step = -1
        action_count = -1
        rows = 0
        cols = 0
        grid = None

        # Parse step and action count (both are present in both encoding types)
        step_match = re.search(r'Step:\s*(\d+)', obs)
        if step_match:
            step = int(step_match.group(1))
        ac_match = re.search(r'Action count:\s*(\d+)', obs)
        if ac_match:
            action_count = int(ac_match.group(1))

        # ----- Extract grid -----
        # Method A: ARC integer grid (look for <grid_k> markers)
        grid_match = re.search(r'<grid_\d+>', obs)
        if grid_match:
            marker_end = grid_match.end()
            lines_after = obs[marker_end:].strip().split('\n')
            int_rows = []
            for line in lines_after:
                line = line.strip()
                if line.startswith('[') and line.endswith(']'):
                    try:
                        row_str = line[1:-1]
                        row = [int(x.strip()) for x in row_str.split(',')]
                        if row:
                            int_rows.append(row)
                    except (ValueError, IndexError):
                        continue
                elif line == '' or line.startswith('<') or line.startswith('='):
                    if int_rows:
                        break
                    continue
            if int_rows:
                grid = int_rows
                rows = len(grid)
                cols = len(grid[0]) if rows > 0 else 0

        # Method B: JSON string grid (2D array of color names)
        if grid is None:
            start = obs.find('[[')
            end = obs.rfind(']]')
            if start != -1 and end != -1:
                try:
                    grid_json = obs[start:end+2]
                    parsed = json.loads(grid_json)
                    if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                        grid = parsed
                        rows = len(grid)
                        cols = len(grid[0]) if rows > 0 else 0
                except (json.JSONDecodeError, IndexError):
                    pass

        # Fallback: try to find any JSON array pattern
        if grid is None:
            for pattern in [r'\[\[.*?\]\]', r'\[.*?\]']:
                match = re.search(pattern, obs, re.DOTALL)
                if match:
                    candidate = match.group()
                    try:
                        parsed = json.loads(candidate)
                        if isinstance(parsed, list) and len(parsed) > 0:
                            if isinstance(parsed[0], list):
                                grid = parsed
                                rows = len(grid)
                                cols = len(grid[0]) if rows > 0 else 0
                                break
                    except (json.JSONDecodeError, AttributeError):
                        continue

        if grid is None:
            # Last resort: return minimal info with step/action_count if available
            parts = [f"step={step}", f"ac={action_count}"]
            return " ".join(parts) if any(parts) else "(empty)"

        # ----- Analyse grid -----
        # Count color frequencies
        color_counts = {}
        for row in grid:
            for cell in row:
                color_counts[cell] = color_counts.get(cell, 0) + 1

        if not color_counts:
            return f"step={step} ac={action_count} grid=0x0"

        # Determine background (most frequent colour)
        background = max(color_counts, key=color_counts.get)

        # Collect non-background cells
        non_bg_cells: List[Tuple[int, int, str]] = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell != background:
                    if isinstance(cell, int):
                        color_name = _int_to_color_name(cell)
                    else:
                        color_name = _short_color_name(str(cell))
                    non_bg_cells.append((r, c, color_name))

        # Build summary parts
        summary_parts = []
        # Include step and action count always, even if -1 (so they are distinguishable)
        summary_parts.append(f"step={step}")
        summary_parts.append(f"ac={action_count}")
        summary_parts.append(f"grid={rows}x{cols}")
        summary_parts.append(f"bg={_color_to_str(background)}")

        if non_bg_cells:
            # Group cells by colour
            cells_by_color: dict = {}
            for r, c, color in non_bg_cells:
                cells_by_color.setdefault(color, []).append((r, c))
            color_parts = []
            for color, positions in sorted(cells_by_color.items()):
                pos_str = ";".join([f"{r},{c}" for r, c in sorted(positions)])
                color_parts.append(f"{color}:{pos_str}")
            summary_parts.append("objs=" + "|".join(color_parts))
        else:
            summary_parts.append("objs=none")

        # Build final string, ensure it does not exceed 2000 chars
        result = " ".join(summary_parts)
        if len(result) > 2000:
            # Truncate by shortening long position lists
            # We'll re‑build with a limit on total positions
            max_positions = 200
            if non_bg_cells:
                all_positions = []
                for color, positions in cells_by_color.items():
                    for pos in positions:
                        all_positions.append((color, pos))
                # take first max_positions
                all_positions = all_positions[:max_positions]
                # re‑group
                cells_by_color_short = {}
                for color, pos in all_positions:
                    cells_by_color_short.setdefault(color, []).append(pos)
                color_parts = []
                for color, positions in sorted(cells_by_color_short.items()):
                    pos_str = ";".join([f"{r},{c}" for r, c in sorted(positions)])
                    color_parts.append(f"{color}:{pos_str}")
                summary_parts = [p for p in summary_parts if not p.startswith("objs=")]
                summary_parts.append("objs=" + "|".join(color_parts))
                result = " ".join(summary_parts)
            if len(result) > 2000:
                result = result[:1997] + "..."

        return result

    except Exception as e:
        # Never raise, return a safe non‑empty string with step info if possible
        try:
            fallback_step = re.search(r'Step:\s*(\d+)', observation_history[-1])
            s = f"step={fallback_step.group(1)}" if fallback_step else ""
        except Exception:
            s = ""
        return f"(error:{s})" if s else "(unknown_error)"


def _int_to_color_name(val: int) -> str:
    """Convert integer color code to short name string."""
    color_map = {
        0: "blk",    # black
        1: "blu",    # blue
        2: "red",    # red
        3: "grn",    # green
        4: "ylw",    # yellow
        5: "lgry",   # light-gray
        6: "mag",    # magenta
        7: "orn",    # orange
        8: "lblu",   # light-blue
        9: "mrn",    # maroon
        10: "wht",   # white
        11: "dgry",  # dark-gray
    }
    return color_map.get(val, f"c{val}")


def _short_color_name(name: str) -> str:
    """Convert full colour name to short abbreviation."""
    mapping = {
        "black": "blk",
        "blue": "blu",
        "red": "red",
        "green": "grn",
        "yellow": "ylw",
        "gray": "gry",
        "lightgray": "lgry",
        "light-gray": "lgry",
        "magenta": "mag",
        "orange": "orn",
        "lightblue": "lblu",
        "light-blue": "lblu",
        "darkgreen": "dgrn",
        "dark-red": "mrn",
        "maroon": "mrn",
        "white": "wht",
        "darkgray": "dgry",
        "dark-gray": "dgry",
        "gold": "gld",
    }
    return mapping.get(name.lower(), name[:4])


def _color_to_str(color) -> str:
    """Convert a color value (int or str) to short string."""
    if isinstance(color, int):
        return _int_to_color_name(color)
    elif isinstance(color, str):
        return _short_color_name(color)
