import json
import re
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation and output a concise text summary.
    The output includes the step count, action count, and a delta of changes
    from the previous observation (if available). If no previous observation,
    outputs a full summary of the grid's non-background cells.
    Never raises, never returns empty.
    """
    try:
        obs = observation_history[-1]
        # Parse step and action count for context
        step = _extract_int(obs, r'Step:\s*(\d+)', default=0)
        action_cnt = _extract_int(obs, r'Action count:\s*(\d+)', default=0)

        # Parse current grid
        grid = _parse_grid(obs)
        if grid is None:
            return f"step={step} cnt={action_cnt} (grid_parse_failed)"

        # Compute a compact representation of the current grid (for delta)
        cur_repr = _grid_to_repr(grid)

        # If we have a previous observation, compute delta
        delta_str = ""
        if len(observation_history) >= 2:
            prev_obs = observation_history[-2]
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is not None:
                prev_repr = _grid_to_repr(prev_grid)
                delta = _compute_delta(prev_repr, cur_repr)
                if delta:
                    # Format delta: "changed: (r,c) old->new; ..."
                    parts = []
                    for (r, c, old, new) in delta:
                        parts.append(f"({r},{c}) {_color_short(old)}->{_color_short(new)}")
                    delta_str = "delta=" + ";".join(parts)
                else:
                    delta_str = "delta=none"
            else:
                # fallback: cannot parse previous grid
                delta_str = "delta=unknown"
        else:
            # First state: output full summary of non-background cells
            delta_str = _full_summary(grid)

        # Build output, ensure it's non-empty and under 2000 chars
        output = f"step={step} cnt={action_cnt} {delta_str}"
        if len(output) > 2000:
            # Truncate the delta part if needed
            max_delta = 2000 - len(f"step={step} cnt={action_cnt} ")
            if max_delta > 0:
                delta_str = delta_str[:max_delta]
            output = f"step={step} cnt={action_cnt} {delta_str}"
        return output

    except Exception:
        # Fallback: never raise, never return empty
        return "(perception_error)"

