# Helper functions
# ----------------------------------------------------------------------

def _extract_int(text: str, pattern: str, default: int) -> int:
    """Extract an integer from text using regex, return default if not found."""
    m = re.search(pattern, text)
    if m:
        try:
            return int(m.group(1))
        except ValueError:
            return default
    return default

_COLOR_NAME_TO_INT = {
    "black": 0, "blue": 1, "red": 2, "green": 3, "yellow": 4,
    "light-gray": 5, "gray": 5, "lightgray": 5,
    "magenta": 6, "orange": 7, "light-blue": 8, "lightblue": 8,
    "dark-red": 9, "maroon": 9, "white": 10, "dark-gray": 11, "darkgray": 11,
    "gold": 4  # treat gold as yellow
}
_INT_TO_SHORT = {
    0: "blk", 1: "blu", 2: "red", 3: "grn", 4: "ylw",
    5: "gry", 6: "mag", 7: "orn", 8: "lbl", 9: "mrn",
    10: "wht", 11: "dgy"
}

def _parse_grid(obs: str) -> Optional[List[List[int]]]:
    """Parse the grid from the observation text. Returns list of list of ints (0-11)."""
    # Method 1: ARC integer grid (look for <grid_k> markers)
    m = re.search(r'<grid_\d+>', obs)
    if m:
        marker_end = m.end()
        lines_after = obs[marker_end:].strip().split('\n')
        rows = []
        for line in lines_after:
            line = line.strip()
            if line.startswith('[') and line.endswith(']'):
                try:
                    row_str = line[1:-1]  # remove brackets
                    row = [int(x.strip()) for x in row_str.split(',')]
                    if row:
                        rows.append(row)
                except (ValueError, IndexError):
                    continue
            elif line == '' or line.startswith('<') or line.startswith('='):
                if not rows:
                    continue
                break
        if rows:
            return rows

    # Method 2: JSON 2D array of color name strings
    start = obs.find('[[', obs.find('[')+1 if '[' in obs else 0)
    # Actually find the outermost [[ ... ]]
    start = obs.find('[[')
    end = obs.rfind(']]')
    if start != -1 and end != -1:
        try:
            json_str = obs[start:end+2]
            parsed = json.loads(json_str)
            if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                # Convert color names to integers
                grid = []
                for row in parsed:
                    int_row = []
                    for cell in row:
                        if isinstance(cell, int):
                            int_row.append(cell)
                        elif isinstance(cell, str):
                            c = cell.lower().strip()
                            int_row.append(_COLOR_NAME_TO_INT.get(c, 0))
                        else:
                            int_row.append(0)
                    grid.append(int_row)
                return grid
        except (json.JSONDecodeError, IndexError, TypeError):
            pass

    # Fallback: try to find the first JSON array in the text
    try:
        for pattern in [r'\[\[.*?\]\]', r'\[.*?\]']:
            match = re.search(pattern, obs, re.DOTALL)
            if match:
                candidate = match.group()
                parsed = json.loads(candidate)
                if isinstance(parsed, list) and len(parsed) > 0:
                    if isinstance(parsed[0], list):
                        grid = []
                        for row in parsed:
                            int_row = []
                            for cell in row:
                                if isinstance(cell, int):
                                    int_row.append(cell)
                                elif isinstance(cell, str):
                                    c = cell.lower().strip()
                                    int_row.append(_COLOR_NAME_TO_INT.get(c, 0))
                                else:
                                    int_row.append(0)
                            grid.append(int_row)
                        return grid
    except (json.JSONDecodeError, AttributeError, TypeError):
        pass

    return None

def _grid_to_repr(grid: List[List[int]]) -> List[List[int]]:
    """Return the grid itself (list of lists of ints)."""
    return grid

def _compute_delta(prev: List[List[int]], cur: List[List[int]]) -> List[Tuple[int, int, int, int]]:
    """Return list of (row, col, old_val, new_val) for cells that changed."""
    changes = []
    if not prev or not cur:
        return changes
    rows = min(len(prev), len(cur))
    for r in range(rows):
        cols = min(len(prev[r]), len(cur[r]))
        for c in range(cols):
            if prev[r][c] != cur[r][c]:
                changes.append((r, c, prev[r][c], cur[r][c]))
    return changes

def _color_short(val: int) -> str:
    """Convert integer color to a short 3-letter code."""
    return _INT_TO_SHORT.get(val, f"c{val}")

def _full_summary(grid: List[List[int]]) -> str:
    """Return a summary of non-background cells (for first state)."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    # Count colors to determine background
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    if not counts:
        return f"grid={rows}x{cols} bg=none"
    bg = max(counts, key=counts.get)
    # Collect non-bg cells
    non_bg = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                non_bg.append((r, c, grid[r][c]))
    # Group by color
    by_color = {}
    for r, c, v in non_bg:
        short = _color_short(v)
        by_color.setdefault(short, []).append(f"{r},{c}")
    parts = [f"grid={rows}x{cols}", f"bg={_color_short(bg)}"]
    if by_color:
        obj_parts = []
        for col in sorted(by_color.keys()):
            obj_parts.append(f"{col}:{'|'.join(sorted(by_color[col]))}")
        parts.append("objs=" + ";".join(obj_parts))
    else:
        parts.append("objs=none")
    return " ".join(parts)

