        # Build list of (row, col, color) for non-background cells
        non_bg = _get_non_background_cells(grid)

        # Track object identities across steps
        if 'object_tracker' not in perceive.__dict__:
            perceive.object_tracker = {}

        # Compute a compact representation with object IDs
        objects_with_ids = _assign_objects_ids(non_bg, perceive.object_tracker, step)

        # Format the objects preserving creation order
        obj_str = _format_objects(objects_with_ids)

        # Build grid dimensions info
