def _assign_objects_ids(cells: List[Tuple[int, int, int]], 
                        tracker: Dict, 
                        step: int) -> List[Tuple[str, int, int, int]]:
    """
    Assign stable IDs to objects based on position and color tracking.
    Returns list of (obj_id, row, col, color) tuples.
    """
    # Cells are already in (row, col, color) format
    # We need to track objects across steps for identity preservation

    # Build current state as set of features
    curr_objects = {}
    for r, c, color in cells:
        key = (r, c)
        if key not in curr_objects:
            curr_objects[key] = color

    # Update tracker with new positions
    # Simple approach: match objects by closest position and same color
    if tracker:
        # For each tracked object, find closest match of same color
        matched_tracker_keys = set()
        matched_curr_keys = set()
        new_objects = []

        # First pass: match tracked objects to current objects by position proximity
        for track_id, (prev_r, prev_c, track_color) in tracker.items():
            best_dist = float('inf')
            best_curr_key = None
            for (cr, cc), ccolor in curr_objects.items():
                if (cr, cc) in matched_curr_keys:
                    continue
                if ccolor != track_color:
                    continue
                dist = abs(cr - prev_r) + abs(cc - prev_c)
                if dist < best_dist and dist <= 5:  # Max movement threshold
                    best_dist = dist
                    best_curr_key = (cr, cc)

            if best_curr_key is not None and best_dist <= 5:
                matched_tracker_keys.add(track_id)
                matched_curr_keys.add(best_curr_key)
                # Update tracker with new position
                r, c = best_curr_key
                tracker[track_id] = (r, c, curr_objects[best_curr_key])
                new_objects.append((track_id, r, c, curr_objects[best_curr_key]))

        # Add remaining unmatched current objects as new
        for (r, c), color in curr_objects.items():
            if (r, c) not in matched_curr_keys:
                new_id = f"o{len(tracker)}"
                tracker[new_id] = (r, c, color)
                new_objects.append((new_id, r, c, color))

        # Clean up tracker entries for objects no longer present
        for track_id in list(tracker.keys()):
            if track_id not in matched_tracker_keys and track_id not in [o[0] for o in new_objects if o[0] not in matched_tracker_keys]:
                # Check if this object might have been merged
                track_r, track_c, track_color = tracker[track_id]
                still_present = False
                for r, c, color in cells:
                    if color == track_color and abs(r - track_r) + abs(c - track_c) <= 5:
                        still_present = True
                        break
                if not still_present:
                    del tracker[track_id]

        return new_objects
    else:
        # First step: create initial IDs
        objects = []
        for i, (r, c, color) in enumerate(cells):
            obj_id = f"o{i}"
            tracker[obj_id] = (r, c, color)
            objects.append((obj_id, r, c, color))
        return objects

def _format_objects(objects: List[Tuple[str, int, int, int]]) -> str:
    """
    Format objects preserving creation order.
    Use '|' between same color objects, ';' between different colors.
    """
    if not objects:
        return ""

    # Group objects by color while preserving order
    parts = []
    current_color = objects[0][3]
    current_group = []

    for obj_id, r, c, color in objects:
        if color == current_color:
            current_group.append(f"{r},{c}")
        else:
            # Output previous group
            col_short = _color_short(current_color)
            parts.append(f"{col_short}:{'|'.join(current_group)}")
            current_color = color
            current_group = [f"{r},{c}"]

    # Output last group
    col_short = _color_short(current_color)
    parts.append(f"{col_short}:{'|'.join(current_group)}")

    return ";".join(parts)

