def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation and output a concise text summary.
    The output includes the step count, action count, grid info, and a 
    *deterministically ordered* representation of non-background cells 
    sorted by (color, row, col) so that object identity is stable and 
    changes (including in-place color changes) are visible in the order.
    Never raises, never returns empty.
    """
    try:
        obs = observation_history[-1]
        step = _extract_int(obs, r'Step:\s*(\d+)', default=0)
        action_cnt = _extract_int(obs, r'Action count:\s*(\d+)', default=0)
        task_type = _extract_task_type(obs)

