        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        bg = _get_background_color(grid)
        bg_short = _color_short(bg)

        # Extract all non-background cells, sorted deterministically
        # by (color, row, col) so that a color change in place preserves
        # the same relative position in the sorted order (since (row,col) fixed).
        # This makes forward prediction consistent: if a gray cell at (0,0)
        # becomes red, its sorting key changes from (gry,0,0) to (red,0,0),
        # which may shift it relative to other cells – but that shift is
        # *deterministic* and predictable from the color change alone.
        cells = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != bg:
                    cells.append((grid[r][c], r, c))
        cells.sort(key=lambda x: (x[0], x[1], x[2]))

        # Build compact string: group by color, within color list (r,c)
        parts = []
        if cells:
            current_color = cells[0][0]
            group_positions = []
            for color, r, c in cells:
                if color != current_color:
                    col_short = _color_short(current_color)
                    parts.append(f"{col_short}:{','.join(f'{rr},{cc}' for rr,cc in group_positions)}")
                    current_color = color
