            parts.append(f"{col_short}:{','.join(f'{rr},{cc}' for rr,cc in group_positions)}")
            objs_str = ";".join(parts)
        else:
            objs_str = "none"

        output = f"step={step} cnt={action_cnt} grid={rows}x{cols} bg={bg_short} objs={objs_str}"

        if len(output) > 2000:
            output = output[:1997] + "..."

        return output

    except Exception as e:
        return f"(perception_error: {str(e)})"


