import json
import re
from typing import List, Tuple, Optional, Dict, Any, Set

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation and output a concise text summary.
    Includes:
    - Step, action count, task type.
    - Grid dimensions and background color.
    - Non‑background objects sorted by first‑appearance (creation time) for forward predictability.
    - Changes from the immediately preceding observation (if any) to aid inverse dynamics.
    - Any explicit click coordinate mentioned in the observation text.
    Never raises, never returns empty.
    """
    try:
        obs = observation_history[-1]
        step = _extract_int(obs, r'Step:\s*(\d+)', default=0)
        action_cnt = _extract_int(obs, r'Action count:\s*(\d+)', default=0)
        task_type = _extract_task_type(obs)

        grid = _parse_grid(obs)
        if grid is None:
            return f"step={step} cnt={action_cnt} task={task_type} (grid_parse_failed)"

        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        bg = _get_background_color(grid)
        bg_short = _color_short(bg)

        # compute current set of non‑background cells
        current_cells = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != bg:
                    current_cells.append((grid[r][c], r, c))

        # ----- determine object order by creation time -----
        # Use all available history to find first timestamp for each (color,row,col) pair.
        # For consistent cross‑call ordering, we build a mapping using every observation in history.
        first_occurrence = {}
        # parse all preceding observations
        for t, prev_obs in enumerate(observation_history[:-1]):
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is None:
                continue
            prev_bg = _get_background_color(prev_grid) if prev_grid else 0
            for r in range(len(prev_grid)):
                for c in range(len(prev_grid[0])):
                    val = prev_grid[r][c]
                    if val != prev_bg:
                        key = (val, r, c)
                        if key not in first_occurrence:
                            first_occurrence[key] = t  # use index as timestamp
        # also assign timestamp to the current observation (if not yet seen) – use len(history)-1
        curr_timestamp = len(observation_history) - 1
        # determine timestamps for current cells
        cell_order = []
        for cell in current_cells:
            key = cell
            ts = first_occurrence.get(key, curr_timestamp)
            cell_order.append((ts, cell[1], cell[2], cell[0]))  # (timestamp, row, col, color)
        # sort: timestamp ascending (older first), then row, then col for stability
        cell_order.sort()
        # build objs string in that order
        objs_parts = []
        for _, r, c, col in cell_order:
            col_short = _color_short(col)
            objs_parts.append(f"{col_short}:{r},{c}")
        objs_str = ";".join(objs_parts) if objs_parts else "none"
        cell_count = len(objs_parts)

        # ----- detect changes from previous state -----
        diff_str = ""
        if len(observation_history) >= 2:
            prev_obs = observation_history[-2]
            prev_grid = _parse_grid(prev_obs)
            if prev_grid is not None:
                prev_bg = _get_background_color(prev_grid)
                # convert both to sets of (color,row,col)
                curr_set = set(current_cells)
                prev_set = set()
                for r in range(len(prev_grid)):
                    for c in range(len(prev_grid[0])):
                        if prev_grid[r][c] != prev_bg:
                            prev_set.add((prev_grid[r][c], r, c))
                # compute added and removed cells
                added = curr_set - prev_set
                removed = prev_set - curr_set
                diff_parts = []
                for col, r, c in sorted(added, key=lambda x: (x[1], x[2])):
                    diff_parts.append(f"+{_color_short(col)}:{r},{c}")
                for col, r, c in sorted(removed, key=lambda x: (x[1], x[2])):
                    diff_parts.append(f"-{_color_short(col)}:{r},{c}")
                if diff_parts:
                    diff_str = " diff=" + ",".join(diff_parts)

        # ----- check for explicit click coordinate in observation text -----
        click_info = ""
        # look for patterns like "click at (2,14)" or "clicked (9,12)" or "cursor at (3,3)"
        click_pattern = r'(?:click|clicked|cursor)\s*(?:at|on|to)?\s*\(?\s*(\d+)\s*,?\s*(\d+)\s*\)?'
        m = re.search(click_pattern, obs, re.IGNORECASE)
        if m:
            row = int(m.group(1))
            col = int(m.group(2))
            click_info = f" click_candidate=({row},{col})"
        else:
            # maybe the click coordinate appears as a line: "click ROW COL" in available actions but that's the list, not what was taken.
            # We'll only report if it's explicitly a past action.
            pass

        # ----- assemble output -----
        output = (f"step={step} cnt={action_cnt} task={task_type} "
                  f"grid={rows}x{cols} bg={bg_short} "
                  f"objs_count={cell_count} objs={objs_str}"
                  f"{diff_str}{click_info}")

        # Ensure length limit
        if len(output) > 2000:
            output = output[:1997] + "..."

        return output

    except Exception as e:
        return f"(perception_error: {str(e)})"


