      Action taken: noop
    Returns the action string (e.g. "click 3 3") or empty string if not found.
    """
    # Try "Action:" followed by any text
    m = re.search(r'^Action\s*:\s*(.+)$', text, re.MULTILINE | re.IGNORECASE)
    if m:
        action_str = m.group(1).strip()
        # Remove trailing punctuation, ensure reasonable length
        if len(action_str) > 50:
            action_str = action_str[:50]
        return action_str
    # Try "Action taken:"
    m = re.search(r'^Action taken\s*:\s*(.+)$', text, re.MULTILINE | re.IGNORECASE)
    if m:
