def _extract_int(text: str, pattern: str, default: int) -> int:
    m = re.search(pattern, text)
    if m:
        try:
            return int(m.group(1))
        except ValueError:
            return default
    return default

def _extract_task_type(text: str) -> str:
    m = re.search(r'Task:\s*(\w+)', text)
    return m.group(1) if m else "unknown"

def _extract_phase(text: str) -> str:
    m = re.search(r'Phase:\s*(.+?)\s*(?:\n|$)', text)
    return m.group(1).strip() if m else "unknown"

def _extract_action(text: str) -> str:
    """
    Extract the action that was taken from the observation text.
    Look for lines like:
      Action taken: click 9 12
      Action: click 2 14
      Action: noop
    Returns the action string (e.g. "click 9 12") or empty string if not found.
    """
    # Split into lines for robust pattern matching
    lines = text.split('\n')
    for line in lines:
        stripped = line.strip()
        # Skip lines that are just "Available actions now:" or similar
        if stripped.lower().startswith("available"):
            continue
        # Match lines that start with "Action" (case-insensitive) and contain a colon or equals
        # e.g. "Action taken: click 3 3" or "Action: noop"
        m = re.match(r'^Action\s+(?:taken\s*)?[:=]\s*(.+)$', stripped, re.IGNORECASE)
        if m:
            action = m.group(1).strip()
            # Filter out spurious captures (e.g. if the line is just "Action:")
            if action and not action.lower().startswith("available"):
                return action
        # Also try "The action was: ..." pattern
        m = re.match(r'^The\s+action\s+(?:was|is)\s*[:=]\s*(.+)$', stripped, re.IGNORECASE)
        if m:
            action = m.group(1).strip()
            if action:
                return action
    # Fallback: search the whole text with a more general pattern (multiline)
    patterns = [
        r'(?:^|\n)\s*Action\s+taken\s*[:=]\s*(.+?)\s*(?:\n|$)',
        r'(?:^|\n)\s*Action\s*[:=]\s*(.+?)\s*(?:\n|$)',
        r'(?:^|\n)\s*The\s+action\s+(?:was|is)\s*[:=]\s*(.+?)\s*(?:\n|$)',
    ]
    for pat in patterns:
        m = re.search(pat, text, re.IGNORECASE | re.MULTILINE)
        if m:
            action_str = m.group(1).strip()
            if len(action_str) > 60:
                action_str = action_str[:60]
            # Exclude lines that contain "available"
            if not action_str.lower().startswith("available"):
                return action_str
    return ""


