def _extract_action(text: str) -> str:
    """
    Extract the action that was taken from the observation text.
    Returns a string like "click 2 14", "noop", or "" if not found.
    """
    # Split into lines for robust pattern matching
    lines = text.split('\n')
    for line in lines:
        stripped = line.strip()
        # Skip lines that are part of "Available actions"
        if stripped.lower().startswith("available"):
            continue
        # Pattern: "Action taken: <action>" or "Action: <action>" or "The action was: <action>"
        m = re.match(r'^(?:Action\s+(?:taken\s*)?|The\s+action\s+(?:was|is)\s*)[:=]\s*(.+)$', stripped, re.IGNORECASE)
        if m:
            action = m.group(1).strip()
            if action and not action.lower().startswith("available"):
                # Further normalize: replace multiple spaces, trim parentheses etc.
                action = re.sub(r'\s+', ' ', action)
                # If it's a click action, ensure exactly two numbers follow "click"
                if action.lower().startswith('click'):
                    nums = re.findall(r'\d+', action)
                    if len(nums) >= 2:
                        action = f"click {nums[0]} {nums[1]}"
                return action
    # Fallback: search the whole text for a multiline pattern (in case line-by-line fails)
