def _extract_int(text: str, pattern: str, default: int) -> int:
    m = re.search(pattern, text)
    if m:
        try:
            return int(m.group(1))
        except ValueError:
            return default
    return default

def _extract_task_type(text: str) -> str:
    m = re.search(r'Task:\s*(\w+)', text)
    return m.group(1) if m else "unknown"

def _extract_phase(text: str) -> str:
    m = re.search(r'Phase:\s*(.+?)\s*(?:\n|$)', text)
    return m.group(1).strip() if m else "unknown"

def _extract_action(text: str) -> str:
    """
    Extract the action that was taken from the observation text.
    Returns a string like "click 2 14", "noop", or "" if not found.
    Handles various phrasings and line formats.
    """
    # Split into lines for robust pattern matching
    lines = text.split('\n')
    for line in lines:
        stripped = line.strip()
        # Skip lines that are part of "Available actions"
        if stripped.lower().startswith("available"):
            continue
        # Pattern: "Action taken: <action>" or "Action: <action>" or "The action was: <action>"
        m = re.match(
            r'^(?:Action\s+(?:taken\s*)?|The\s+action\s+(?:was|is)\s*)[:=]\s*'
            r'(click\s+\d+\s+\d+|noop|quit|reset|left|right|up|down)',
            stripped, re.IGNORECASE
        )
        if m:
            action = m.group(1).strip()
            if action:
                # Normalize whitespace
                action = re.sub(r'\s+', ' ', action)
                # For click actions, ensure exactly two numbers (already matched by pattern)
                if action.lower().startswith('click'):
                    nums = re.findall(r'\d+', action)
                    if len(nums) >= 2:
                        action = f"click {nums[0]} {nums[1]}"
                return action
    # Fallback: search the whole text for a multiline pattern (in case line-by-line fails)
    patterns = [
        r'(?:^|\n)\s*(?:Action\s+(?:taken\s*)?|The\s+action\s+(?:was|is)\s*)[:=]\s*(click\s+\d+\s+\d+)',
        r'(?:^|\n)\s*(?:Action\s+(?:taken\s*)?|The\s+action\s+(?:was|is)\s*)[:=]\s*(noop)',
    ]
    for pat in patterns:
        m = re.search(pat, text, re.IGNORECASE | re.MULTILINE)
        if m:
            action = m.group(1).strip()
            if len(action) > 60:
                action = action[:60]
            return action
    return ""


_COLOR_NAME_TO_INT: Dict[str, int] = {
    "black": 0, "blue": 1, "red": 2, "green": 3, "yellow": 4,
    "light-gray": 5, "gray": 5, "lightgray": 5,
    "magenta": 6, "orange": 7, "light-blue": 8, "lightblue": 8,
    "dark-red": 9, "maroon": 9, "white": 10, "dark-gray": 11, "darkgray": 11,
    "gold": 4
}

_INT_TO_SHORT: Dict[int, str] = {
    0: "blk", 1: "blu", 2: "red", 3: "grn", 4: "ylw",
    5: "gry", 6: "mag", 7: "orn", 8: "lbl", 9: "mrn",
    10: "wht", 11: "dgy"
}

def _color_short(val: int) -> str:
    return _INT_TO_SHORT.get(val, f"c{val}")

def _parse_grid(obs: str) -> Optional[List[List[int]]]:
    """Parse the grid from the observation text. Returns list of list of ints (0-11)."""
    # Method 1: ARC integer grid with <grid_k> markers
    m = re.search(r'<grid_\d+>', obs)
    if m:
        marker_end = m.end()
        lines_after = obs[marker_end:].strip().split('\n')
        rows = []
        for line in lines_after:
            line = line.strip()
            if line.startswith('[') and line.endswith(']'):
                try:
                    row_str = line[1:-1]
                    row = [int(x.strip()) for x in row_str.split(',')]
                    if row:
                        rows.append(row)
                except (ValueError, IndexError):
                    continue
            elif line == '' or line.startswith('<') or line.startswith('='):
                if not rows:
                    continue
                break
        if rows:
            return rows

    # Method 2: JSON 2D array of colour-name strings (contiguous)
    start = obs.find('[[')
    end = obs.rfind(']]')
    if start != -1 and end != -1 and end > start:
        try:
            json_str = obs[start:end+2]
            parsed = json.loads(json_str)
            if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                grid = []
                for row in parsed:
                    int_row = []
                    for cell in row:
                        if isinstance(cell, int):
                            int_row.append(cell)
                        elif isinstance(cell, str):
                            c = cell.lower().strip()
                            int_row.append(_COLOR_NAME_TO_INT.get(c, 0))
                        else:
                            int_row.append(0)
                    grid.append(int_row)
                return grid
        except (json.JSONDecodeError, IndexError, TypeError):
            pass

    # Fallback: try to find any JSON array in the text
    try:
        for pattern in [r'\[\[.*?\]\]', r'\[.*?\]']:
            match = re.search(pattern, obs, re.DOTALL)
            if match:
                candidate = match.group()
                parsed = json.loads(candidate)
                if isinstance(parsed, list) and len(parsed) > 0:
                    if isinstance(parsed[0], list):
                        grid = []
                        for row in parsed:
                            int_row = []
                            for cell in row:
                                if isinstance(cell, int):
                                    int_row.append(cell)
                                elif isinstance(cell, str):
                                    c = cell.lower().strip()
                                    int_row.append(_COLOR_NAME_TO_INT.get(c, 0))
                                else:
                                    int_row.append(0)
                            grid.append(int_row)
                        return grid
    except (json.JSONDecodeError, AttributeError, TypeError):
        pass

    return None

def _get_background_color(grid: List[List[int]]) -> int:
    counts: Dict[int, int] = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    if not counts:
        return 0
    return max(counts, key=counts.get)

